/* Local ZIP export: no server or external dependency. */
(function(root){
const OBJ=typeof module!=='undefined'?require('./pro100-obj.js'):Pro100OBJ;
const enc=new TextEncoder();
function zip(files){const local=[],central=[];let offset=0;const crc=bytes=>{let c=0xffffffff;for(const b of bytes){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0};const header=n=>{const a=new Uint8Array(n);return [a,new DataView(a.buffer)]};for(const [path,text] of Object.entries(files)){const name=enc.encode(path),bytes=enc.encode(text),sum=crc(bytes),[h,v]=header(30);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,sum,true);v.setUint32(18,bytes.length,true);v.setUint32(22,bytes.length,true);v.setUint16(26,name.length,true);local.push(h,name,bytes);const [c,d]=header(46);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint16(14,33,true);d.setUint32(16,sum,true);d.setUint32(20,bytes.length,true);d.setUint32(24,bytes.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);central.push(c,name);offset+=h.length+name.length+bytes.length}const size=central.reduce((s,x)=>s+x.length,0),[end,e]=header(22);e.setUint32(0,0x06054b50,true);e.setUint16(8,central.length/2,true);e.setUint16(10,central.length/2,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);const result=new Uint8Array(offset+size+22);let cursor=0;for(const chunk of [...local,...central,end]){result.set(chunk,cursor);cursor+=chunk.length}return result}
const csv=v=>'"'+String(v).replaceAll('"','""')+'"';
function files(rooms,options={}){
const combined=OBJ.build(rooms,options),vertices=[],parts=[];let part=null;
for(const line of combined.trim().split('\n')){const [key,...tail]=line.split(' ');if(key==='o'){part={name:tail.join(' '),faces:[]};parts.push(part)}else if(key==='v')vertices.push(tail.map(Number));else if(key==='f')part.faces.push(tail.map(Number))}
const out={},materials=[],rows=[['Plik / obiekt','Min X OBJ mm','Min Y OBJ mm (wysokosc)','Min Z OBJ mm','Szerokosc X','Wysokosc Y','Glebokosc Z','Punkt REF X','Punkt REF Y','Punkt REF Z']];
const allBounds={min:[Infinity,Infinity,Infinity],max:[-Infinity,-Infinity,-Infinity]};
for(const p of parts){if(!p.faces.length)continue;const ids=[...new Set(p.faces.flat())],min=[0,1,2].map(k=>Math.min(...ids.map(i=>vertices[i-1][k]))),max=[0,1,2].map(k=>Math.max(...ids.map(i=>vertices[i-1][k])));for(let k=0;k<3;k++){allBounds.min[k]=Math.min(allBounds.min[k],min[k]);allBounds.max[k]=Math.max(allBounds.max[k],max[k])}const mapping=new Map(ids.map((id,i)=>[id,i+1]));const color=p.name.includes('_REF_')?'0.95 0.15 0.12':p.name.includes('_water_')?'0.15 0.65 0.75':/_(podloga|sufit|sciana)_?/.test(p.name)?'0.75 0.81 0.86':'0.95 0.65 0.20';const material=`newmtl ${p.name}\nKa 0.2 0.2 0.2\nKd ${color}\nKs 0 0 0\nd 1\nillum 1\n`;materials.push(material);out['elementy/'+p.name+'.obj']=['# Independent object; local minimum is 0,0,0; restore position using polozenia.csv','mtllib '+p.name+'.mtl','o '+p.name,'usemtl '+p.name,...ids.map(i=>'v '+vertices[i-1].map((x,k)=>+(x-min[k]).toFixed(4)).join(' ')),...p.faces.map(f=>'f '+f.map(i=>mapping.get(i)).join(' '))].join('\n')+'\n';out['elementy/'+p.name+'.mtl']=material;rows.push([p.name,...min,...max.map((x,k)=>+(x-min[k]).toFixed(4)),...(p.name.includes('_REF_')?min:['','',''])])}
out['KiMapka.obj']=combined;out['KiMapka.mtl']=materials.join('\n');out['polozenia.csv']='\ufeff'+rows.map(row=>row.map(csv).join(';')).join('\r\n');
const pointRows=[['Pokoj','Nazwa','Typ','Powierzchnia','X pomiar mm','Y pomiar mm','Z pomiar mm','REF X OBJ mm','REF Y OBJ mm','REF Z OBJ mm']];
for(const r of rooms)for(const e of r.elements){if(['door','window','obstacle','vent'].includes(e.type)||options.points===false)continue;let p;if(e.wall<0)p=[r.x+e.x,e.wall===-2?r.h-e.z:e.z,-(r.y+e.y)];else{const a=r.points[e.wall],b=r.points[(e.wall+1)%r.points.length],L=Math.hypot(b.x-a.x,b.y-a.y);p=[r.x+a.x+(b.x-a.x)*e.x/L,e.y,-(r.y+a.y+(b.y-a.y)*e.x/L)]}pointRows.push([r.name,e.name||e.type,e.type,e.wall===-1?'Podloga':e.wall===-2?'Sufit':String.fromCharCode(65+e.wall),e.x,e.y,e.z||0,...p.map(n=>+n.toFixed(4))])}
out['punkty.csv']='\ufeff'+pointRows.map(row=>row.map(csv).join(';')).join('\r\n');
out['CZYTAJ.txt']=`KiMapka — eksport rozdzielony do PRO100\n\n1. Rozpakuj CALE archiwum ZIP. Pliki OBJ i MTL musza zostac obok siebie.\n2. PRO100: Plik > Import > Model 3D > KiMapka.obj. Jednostka: mm.\n3. ZAZNACZ opcje „Rozdziel bryly po materiale”. Kazda sciana, podloga, przeszkoda, punkt i znacznik REF ma wlasny material. Nie lacz materialow o podobnym kolorze.\n4. Jesli importer tworzy grupe, rozgrupuj ja zgodnie z funkcjami swojej wersji programu. Jesli podzial nie jest dostepny, importuj pojedyncze pliki z folderu elementy.\n\nPUNKTY ODNIESIENIA\nKrzyzyk ma srodek w zmierzonym punkcie. Osobny czerwony obiekt REF ma wierzcholek dokladnie w tym punkcie i rozmiar 5 x 5 x 5 mm. Jego minimalny naroznik X/Y/Z pokrywa sie z punktem pomiaru. Pozwala wybrac sam znacznik bez sciany i odczytac jego polozenie. To geometria pomocnicza, nie natywny uchwyt pomiarowy PRO100. Obslugi przyciagania do wierzcholka nie potwierdzono.\n\nPOLOZENIE I OSIE\nOBJ: X w prawo, Y wysokosc, Z = minus Y rzutu KiMapki. Wspolrzedne punktow: punkty.csv. Polozenia minimalnych naroznikow i wymiary kazdego obiektu: polozenia.csv.\nModel zbiorczy ma minimum ${allBounds.min.join(', ')} mm i maksimum ${allBounds.max.join(', ')} mm. Importer moze przesunac model do zera lub miejsca wstawienia. Po takim przesunieciu dodaj ten sam wektor do wszystkich wspolrzednych CSV.\nPliki pojedyncze sa ustawione lokalnie od 0,0,0. Po imporcie ustaw ich polozenie wedlug polozenia.csv, uwzgledniajac przesuniecie calego modelu i uklad osi programu. Nie zakladaj, ze osobne importy automatycznie zachowaja wzajemne polozenie.\n\nZAKRES EDYCJI\nOddzielne siatki pozwalaja wybierac i przesuwac elementy zgodnie z mozliwosciami PRO100. Nie sa natywnymi parametrycznymi gniazdkami, scianami ani wymiarami. Zmiana typu i wspolrzednych pomiaru nadal odbywa sie w KiMapce. Zdjecia i uwagi nie sa przenoszone. Glebokosc sciennych przeszkod jest umowna (100 mm), grubosc scian z zapisanego pomiaru lub (gdy brak pomiaru) ustawienia eksportu. Polaczone sciany wypelniaja zapisany odstep; przy eksporcie obu pokojow kazda zajmuje polowe przegrody. Narozniki zewnetrzne maja oddzielne laczniki. Otwory pozostaja puste.\n\nImport koncowy w PRO100 wymaga sprawdzenia w Twojej wersji programu.\n`;
return out}
const api={files,zip};if(typeof module!=='undefined')module.exports=api;else root.Pro100Package=api;
})(typeof globalThis!=='undefined'?globalThis:this);
